using System.Windows.Controls; using TSL.HMI.Models; namespace TSL.HMI.Views; public partial class DiagnosticsView:UserControl{readonly MachineDefinition _m;public DiagnosticsView(MachineDefinition m){InitializeComponent();_m=m;Grid.ItemsSource=m.Tags;}void Search_Changed(object s,TextChangedEventArgs e){var q=Search.Text.Trim();Grid.ItemsSource=string.IsNullOrEmpty(q)?_m.Tags:_m.Tags.Where(x=>(x.Controller+" "+x.Section+" "+x.Description+" "+x.Variable).Contains(q,StringComparison.OrdinalIgnoreCase)).ToList();}}